INSERT INTO `emailtemplates` (`id`, `TemplateName`, `TemplateText`, `Subject`, `SenderName`, `SenderEmail`) VALUES ('141', 'APPLICANT_INITIATED_APPLICATION_SUBMITTED', '<html><head></head><body>    <table border="0" width="100%" cellspacing="0" cellpadding="0" align="center" bgcolor="#FFFFFF">        <tbody>            <tr>                <td                    style="width: 100%; vertical-align: middle; text-align: left; padding: 14px 24px; border-bottom: 3px solid #0A78D1; font-family: sans-serif; font-weight: 400;">                    <img style="display: inline-blaock; float: left; vertical-align: middle;"                        src="https://i.imgur.com/YWp6idv.png" alt="logo"></td>            </tr>            <tr>                <td                    style="width: 100%; vertical-align: middle; text-align: left; padding: 25px 23px 0 23px; font-family: sans-serif; font-weight: 400;">                    <span                        style="font-family: sans-serif; font-size: 12px; font-weight: 400; line-height: 14px; color: #000000; display: inline-block;">Welcome</span><span                        style="font-family: sans-serif; font-size: 12px; font-weight: 400; line-height: 14px; color: #000000; display: inline-block;">&nbsp;</span><span                        style="font-family: sans-serif; font-size: 12px; font-weight: bold; line-height: 14px; color: #000000; display: inline-block;">%FirstName%                        %LastName%!!</span></td>            </tr>            <tr>                <td                    style="width: 100%; vertical-align: middle; text-align: left; padding: 20px 23px 0 23px; font-family: sans-serif; font-weight: 300;">                    <span                        style="font-family: sans-serif; font-size: 12px; font-weight: 400; line-height: 14px; color: #000000; display: inline-block;">Good news! Your initial evaluation                         is now complete and we are now working on sending you the first set of documents, subject to credit checks. You will hear back from us shortly with further updates.</span></td>            </tr>            <tr>                <td                    style="width: 100%; vertical-align: middle; text-align: left; padding: 1px 23px 0 23px; font-family: sans-serif; font-weight: 300;">                    <span                        style="font-family: sans-serif; font-size: 12px; font-weight: 400; line-height: 14px; color: #000000; display: inline-block;">Application                        number : <strong>%ApplicationId%</strong></span></td>            </tr>            <tr>                <td                    style="width: 100%; vertical-align: middle; text-align: left; padding: 1px 23px 0 23px; font-family: sans-serif; font-weight: 300;">                    <span                        style="font-family: sans-serif; font-size: 12px; font-weight: 400; line-height: 14px; color: #000000; display: inline-block;">                        Created on:<strong>%StartDate%</strong></span></td>            </tr>            <tr>                <td                    style="width: 100%; vertical-align: middle; text-align: left; padding: 20px 23px 0 23px; font-family: sans-serif; font-weight: 300;">                    <span                        style="font-family: sans-serif; font-size: 12px; font-weight: 400; line-height: 14px; color: #000000; display: inline-block;">Regards,                    </span></td>            </tr>            <tr>                <td                    style="width: 100%; vertical-align: middle; text-align: left; padding: 4px 23px 27px 23px; font-family: sans-serif; font-weight: 300; border-bottom: 1px solid #0A78D1;">                    <span                        style="font-family: sans-serif; font-size: 12px; font-weight: bold; line-height: 14px; color: #000000; display: inline-block;">Temenos Digital                        Bank</span></td>            </tr>            <tr>                <td                    style="width: 100%; vertical-align: middle; text-align: left; padding: 17px 23px 0px 23px; font-family: sans-serif; font-weight: 300;">                    <span                        style="font-family: sans-serif; font-size: 11px; font-weight: 400; line-height: 13px; color: #000000; display: inline-block;">This                        is a system generated mail. Please do not reply to this e-mail address.</span></td>            </tr>            <tr>                <td                    style="width: 100%; vertical-align: middle; text-align: left; padding: 7px 23px 0px 23px; font-family: sans-serif; font-weight: 300;">                    <span                        style="font-family: sans-serif; font-size: 12px; font-weight: bold; line-height: 14px; color: #000000; display: inline-block;">Have                        any questions?</span></td>            </tr>            <tr>                <td                    style="width: 100%; vertical-align: middle; text-align: left; padding: 7px 23px 0px 23px; font-family: sans-serif; font-weight: 300;">                    <div                        style="width: 100%; display: inline-block; padding: 18px 11px; vertical-align: middle; text-align: left; border-radius: 3px; border: 1px solid #E6E6E6; background-color: #ffffff;">                        <span                            style="font-family: sans-serif; font-size: 12px; font-weight: 400; line-height: 14px; color: #000000; display: inline-block;">Call                            us at</span> <span                            style="font-family: sans-serif; font-size: 12px; font-weight: bold; line-height: 14px; color: #000000; display: inline-block;">&nbsp;1-800-412-5434&nbsp;</span>                        <span                            style="font-family: sans-serif; font-size: 12px; font-weight: 400; line-height: 14px; color: #000000; display: inline-block;">for                            assistance.</span></div>                </td>            </tr>            <tr>                <td                    style="width: 100%; vertical-align: middle; text-align: left; padding: 17px 23px 0px 23px; font-family: sans-serif; font-weight: 300;">                    <span                        style="font-family: sans-serif; font-size: 10px; font-weight: 400; line-height: 12px; color: #000000; display: inline-block;">CONFIDENTIALITY                        INFORMATION AND DISCLAIMER</span></td>            </tr>            <tr>                <td                    style="width: 100%; vertical-align: middle; text-align: left; padding: 5px 23px 18px 23px; font-family: sans-serif; font-weight: 300;">                    <span                        style="font-family: sans-serif; font-size: 10px; font-weight: 400; line-height: 12px; color: #000000; display: inline-block;">This                        e-mail message and its attachments may contain confidential, proprietary or legally privileged                        information and is intended solely for the use of the individual or entity to whom it is                        addressed. If you have erroneously received this message, please delete it immediately and                        notify the sender. If you are not the intended recipient of the e-mail message you should not                        disseminate, distribute or copy this e-mail. E-mail transmission cannot be guaranteed to be                        secure or error-free as information could be intercepted, corrupted, lost, destroyed, incomplete                        or contain viruses and the Temenos Digital accepts no liability for any damage caused by the                        limitations of the e-mail transmission.</span></td>            </tr>        </tbody>    </table></body></html>', 'Temenos Digital', 'Temenos Digital', 'dbx_cl@infinity.com');
